type EmployeeDocument = { id: number; employeeId: number; fileName: string; fileUrl: string; mimeType: string; fileSize: number; uploadedBy: string; createdAt: string };
type Account = { id: number; role: AccountRole; accessRole?: AccountRole; name: string; username: string; phone: string; email: string; password: string; employeeId?: number; job?: string; active: boolean };
type EmployeeRequest = { id: number; employeeId: number; kind: RequestKind; title: string; date: string; leaveTypeId?: number; days: number; hours: number; note: string; status: RequestStatus; createdAt: string; decisionBy?: string };
type LeaveType = { id: number; name: string; defaultDays: number; paid: boolean };
