type PayrollPeriod = { id: number; period: string; status: "open" | "review" | "approved" | "closed"; approvedBy?: string };
type Holiday = { id: number; date: string; name: string; paid: boolean; createdBy: string };

const WEEK_DAYS = (() => {
  const names = ["الأحد", "الإثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت"];
  const today = new Date();
  const sunday = new Date(today);
  sunday.setDate(today.getDate() - today.getDay());
  return names.map((day, index) => {
    const date = new Date(sunday);
    date.setDate(sunday.getDate() + index);
    return { day, date: String(date.getDate()).padStart(2, "0") };
  });
})();
const deductionLabels: Record<DeductionType, string> = { quarter: "ربع يوم", half: "نصف يوم", day: "يوم كامل", three: "3 أيام", four: "4 أيام", amount: "مبلغ مالي" };
const deductionQuarters: Record<Exclude<DeductionType, "amount">, number> = { quarter: 1, half: 2, day: 4, three: 12, four: 16 };
const navTranslations: Record<string, string> = { "نظرة عامة": "Dashboard", "التحليلات": "Analytics", "الموظفون": "Employees", "سجل الحضور": "Attendance", "الحضور الشهري": "Monthly attendance", "الطلبات": "Requests", "الجداول": "Schedules", "الرواتب": "Payroll", "العطلات": "Holidays", "الحسابات": "Accounts", "الإعدادات": "Settings" };
