function makeWeek(overrides: Partial<Record<number, Partial<DayPlan>>> = {}): DayPlan[] {
  return WEEK_DAYS.map((item, index) => ({ day: item.day, date: item.date, status: "دوام", start: "08:00", end: "16:00", shiftType: "صباحي", ...overrides[index] }));
}
