  const addEmployeeMutation = trpc.attendance.addEmployee.useMutation();
  const addAccountMutation = trpc.attendance.addAccount.useMutation();
  const deleteAccountMutation = trpc.attendance.deleteAccount.useMutation();
  const promoteAccountMutation = trpc.attendance.promoteAccount.useMutation();
  const updateEmployeeMutation = trpc.attendance.updateEmployee.useMutation();
  const payrollPeriodMutation = trpc.attendance.updatePayrollPeriod.useMutation();
  const overtimeDecisionMutation = trpc.attendance.decideOvertime.useMutation();
  const addHolidayMutation = trpc.attendance.addHoliday.useMutation();
  const deleteHolidayMutation = trpc.attendance.deleteHoliday.useMutation();
  const uploadDocumentMutation = trpc.attendance.uploadEmployeeDocument.useMutation();
